<# Pure host guards and mocked session boundary; no native/VM calls. #>
[CmdletBinding()]param()
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$script:checks=0;$workspace=Split-Path -Parent $PSScriptRoot
function Check([bool]$Value,[string]$Message){if(-not$Value){throw $Message};$script:checks++}
function Reject([scriptblock]$Action,[string]$Message){$bad=$false;try{& $Action|Out-Null}catch{$bad=$true};Check $bad $Message}
function Clone($Value){$copy=$Value|ConvertTo-Json -Depth 32|ConvertFrom-Json;if($copy-is[array]){foreach($item in $copy){$item}}else{$copy}}
$path=Join-Path $workspace 'scripts\Invoke-LabConvertedVerification.ps1';$tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseFile($path,[ref]$tokens,[ref]$errors);Check ($errors.Count-eq0) 'Host script parse failed.'
foreach($f in $ast.FindAll({param($n)$n-is[Management.Automation.Language.FunctionDefinitionAst]},$false)){Invoke-Expression $f.Extent.Text}
Import-CVGuards ([IO.File]::ReadAllBytes((Join-Path $workspace 'scripts\Invoke-LabNativeReconstruct.ps1'))) @('Assert-RHBool','Assert-RHInteger')
Import-CVGuards ([IO.File]::ReadAllBytes((Join-Path $PSScriptRoot 'guest\Invoke-GuestNativeProbe.ps1'))) @('Assert-NativeProbeGuid')
Import-CVGuards ([IO.File]::ReadAllBytes((Join-Path $PSScriptRoot 'guest\Invoke-GuestReadOnlyMount.ps1'))) @('Assert-MountBool','Assert-MountSame')
Import-CVGuards ([IO.File]::ReadAllBytes((Join-Path $PSScriptRoot 'guest\Invoke-GuestConvertedVerification.ps1'))) @('Assert-ConvertedBool','Assert-ConvertedResult')
$hash='a'*64;$run='b'*32;$review=[pscustomobject]@{schemaVersion=1;kind='converted-verification-reviewed-sources';files=@(Get-CVSources|ForEach-Object{[pscustomobject]@{path=$_;sha256=$hash}})};Assert-CVReviewed $review;$script:checks++
foreach($field in @('schemaVersion','kind')){$bad=Clone $review;$bad.$field='wrong';Reject {Assert-CVReviewed $bad} 'Wrong review accepted.'};$bad=Clone $review;$bad.files=$bad.files[0..14];Reject {Assert-CVReviewed $bad} 'Incomplete review accepted.'
foreach($i in 0..($review.files.Count-1)){$bad=Clone $review;$bad.files[$i].path='../other';Reject {Assert-CVReviewed $bad} 'Unreviewed source accepted.';$bad=Clone $review;$bad.files[$i].sha256='bad';Reject {Assert-CVReviewed $bad} 'Malformed source pin accepted.'}
function Phase([string]$Op,[string]$Id){[pscustomobject]@{schemaVersion=1;kind='native-reconstruction-host';operation=$Op;status='native-phase-checkpointed';phase='complete';runId=$run;phaseId=$Id;vmId='eebbfd4e-d964-4aaf-a6e6-5603fb9b6c4c';baselineId='eda059b3-6d50-46bb-bdf4-018b99b5b34f';outcomeCheckpointName=('reconstruct-'+$Op+'-'+$Id);outcomeCheckpointId=[guid]::NewGuid().ToString('D');phaseExported=$true;ticketExported=$true;cleanShutdown=$true;outcomeCheckpointCreated=$true;baselineRestored=$true;memoryRestored=$true;nativeResultVerified=$true;transportCompletionUnknown=$false;guestOperationUnknown=$false;sessionPreserved=$false;conversionQualified=$false;bootQualified=$false;automaticPhaseProgression=$false;requestSha256=$hash;requestPinSha256=$hash;probeResultSha256=$hash;ticketSha256=$hash;nativeReportSha256=$hash;processResultSha256=$hash;reviewedSourcesSha256=$hash;priorResultSha256=$null;inputTicketSha256=$null;selectedCheckpointId=[guid]::NewGuid().ToString('D');selectedCheckpointName='quiescent'}}
$prepare=Phase prepare ('1'*32);$apply=Phase apply ('2'*32);$handoff=Phase handoff ('3'*32);$prepareHash='c'*64;$applyHash='d'*64;$apply.priorResultSha256=$prepareHash;$handoff.priorResultSha256=$applyHash;$apply.inputTicketSha256=$hash;$handoff.inputTicketSha256=$hash;$apply.selectedCheckpointId=$prepare.outcomeCheckpointId;$apply.selectedCheckpointName=$prepare.outcomeCheckpointName;$handoff.selectedCheckpointId=$apply.outcomeCheckpointId;$handoff.selectedCheckpointName=$apply.outcomeCheckpointName
Assert-CVChain $prepare $apply $handoff $prepareHash $applyHash;$script:checks++
foreach($field in @('schemaVersion','kind','operation','status','phase','runId','phaseId','vmId','baselineId','outcomeCheckpointName','outcomeCheckpointId','requestSha256','requestPinSha256','probeResultSha256','ticketSha256','nativeReportSha256','processResultSha256','reviewedSourcesSha256')){$bad=Clone $handoff;$bad.$field='wrong';Reject {Assert-CVChain $prepare $apply $bad $prepareHash $applyHash} ('Bad phase field accepted: '+$field)}
foreach($field in @('phaseExported','ticketExported','cleanShutdown','outcomeCheckpointCreated','baselineRestored','memoryRestored','nativeResultVerified','transportCompletionUnknown','guestOperationUnknown','sessionPreserved','conversionQualified','bootQualified','automaticPhaseProgression')){foreach($v in @('false',0,(-not$handoff.$field))){$bad=Clone $handoff;$bad.$field=$v;Reject {Assert-CVChain $prepare $apply $bad $prepareHash $applyHash} 'Phase uncertainty/claim accepted.'}}
foreach($field in @('priorResultSha256','inputTicketSha256','selectedCheckpointId','selectedCheckpointName')){$bad=Clone $handoff;$bad.$field='wrong';Reject {Assert-CVChain $prepare $apply $bad $prepareHash $applyHash} 'Broken predecessor link accepted.'}
$bad=Clone $prepare;$bad.priorResultSha256=$hash;Reject {Assert-CVChain $bad $apply $handoff $prepareHash $applyHash} 'Reused prepare predecessor accepted.';$bad=Clone $apply;$bad.operation='resume';Reject {Assert-CVChain $prepare $bad $handoff $prepareHash $applyHash} 'Automatic resume accepted.'
function File([string]$Name,[long]$Length){[pscustomobject]@{name=$Name;length=$Length;sha256=$hash;attributes='Archive'}}
Assert-CVArtifacts @(File attachment.json 1MB) attachment;$script:checks++;Assert-CVArtifacts @(File mount.json 2MB) mount;$script:checks++
$files=@((File input.json 64KB),(File started.json 16KB),(File verification.json 2MB),(File query-000.bin 0),(File query-001.bin 64KB));Assert-CVArtifacts $files verification;$script:checks++
foreach($stage in @('attachment','mount','verification')){Reject {Assert-CVArtifacts @() $stage} 'Empty export accepted.';Reject {Assert-CVArtifacts @(File '..\input.json' 1) $stage} 'Escaping artifact accepted.';Reject {Assert-CVArtifacts @((File input.json 1),(File input.json 1)) $stage} 'Duplicate artifact accepted.'}
foreach($field in @('name','length','sha256','attributes')){$bad=Clone $files;$bad[0].$field=switch($field){name{'other.json'}length{65537}sha256{'bad'}attributes{'ReparsePoint'}};Reject {Assert-CVArtifacts $bad verification} 'Bad artifact field accepted.'}
Reject {Assert-CVArtifacts @(File query-000.bin -1) verification} 'Negative raw length accepted.';Reject {Assert-CVArtifacts @(File input.json 0) verification} 'Empty input accepted.';Reject {Assert-CVArtifacts @(File query-000.bin 65537) verification} 'Oversized query accepted.'
$tooMany=@(0..200|ForEach-Object{File ('query-'+$_.ToString('D3')+'.bin') 0});Reject {Assert-CVArtifacts $tooMany verification} 'More than200 native artifacts accepted.';$tooBig=@(0..64|ForEach-Object{File ('query-'+$_.ToString('D3')+'.bin') 65536});Reject {Assert-CVArtifacts $tooBig verification} 'Raw aggregate over4MiB accepted.'
# Confirm an uncertain phase never removes a session or opens another one.
$spec=[pscustomobject]@{runId=$run;observationId=('9'*32)};$value=[pscustomobject]@{schemaVersion=1;kind='converted-retained-verification';runId=$run;observationId=$spec.observationId;inputSha256=$hash;status='retained-A-observed-through-protected-ReFS';error=$null;input=$spec;nativeOperationCompletionKnown=$true;provenanceValidated=$true;targetWriteRequestsIssued=$false;protectionChanged=$false;mountRequested=$false;conversionQualified=$false;bootQualified=$false;freshVolumeGuid='volume';binaryBytes=5;artifacts=@();native=[pscustomobject]@{status='retained-A-observed-through-protected-ReFS';phase='complete';payloadReadRequests=2;payloadBytesRead=131072;complete=$true;stable=$true;cleanupComplete=$true;privilegeRestored=$true;targetWriteRequestsIssued=$false;protectionChanged=$false;mountRequested=$false;explicitFlushRequested=$false;conversionQualified=$false;bootQualified=$false;payloadHashes=@($hash,$hash);expected=[pscustomobject]@{sourceSha256=$hash;shadowSha256=('b'*64)};openQueries=@();snapshots=@()}}
$files=@((File input.json 10),(File started.json 10),(File verification.json 10));$i=0
foreach($name in @('open','before','after','reopened','final')){$artifact='query-'+$i.ToString('D3')+'.bin';$q=[pscustomobject]@{name='DiskAttributes';api='DeviceIoControl';code=1;inputHex='';capacity=1;bytesReturned=1;succeeded=$true;nativeError=0;artifact=$artifact;sha256=$hash};$value.artifacts+=,[pscustomobject]@{name=$artifact;sha256=$hash;length=1};$files+=,(File $artifact 1);if($name-ceq'open'){$value.native.openQueries=@($q)}else{$value.native.snapshots+=,[pscustomobject]@{name=$name;nativeDiskVerified=$true;readOnlyVolumeVerified=$true;queries=@($q)}};$i++}
$intent=[pscustomobject]@{schemaVersion=1;kind='converted-retained-verification-intent';runId=$run;observationId=$spec.observationId;inputSha256=$hash;freshVolumeGuid='volume';maximumPayloadBytesRead=131072;targetWriteRequestsMayFollow=$false}
Assert-CVVerification $value $intent $spec $hash $files;$script:checks++
foreach($field in @('schemaVersion','kind','runId','observationId','inputSha256','status','error','binaryBytes')){$bad=Clone $value;$bad.$field='wrong';Reject {Assert-CVVerification $bad $intent $spec $hash $files} 'Bad observation evidence accepted.'}
foreach($field in @('nativeOperationCompletionKnown','provenanceValidated','targetWriteRequestsIssued','protectionChanged','mountRequested','conversionQualified','bootQualified')){$bad=Clone $value;$bad.$field=-not$bad.$field;Reject {Assert-CVVerification $bad $intent $spec $hash $files} 'Observation uncertainty/claim accepted.'}
foreach($field in @('complete','stable','cleanupComplete','privilegeRestored')){$bad=Clone $value;$bad.native.$field=$false;Reject {Assert-CVVerification $bad $intent $spec $hash $files} 'Incomplete native observation accepted.'}
foreach($field in @('name','api','code','inputHex','capacity','bytesReturned','succeeded','nativeError','sha256')){$bad=Clone $value;$bad.native.snapshots[3].queries[0].$field='wrong';Reject {Assert-CVVerification $bad $intent $spec $hash $files} 'Changed final native proof accepted.'}
foreach($field in @('nativeDiskVerified','readOnlyVolumeVerified')){$bad=Clone $value;$bad.native.snapshots[0].$field=$false;Reject {Assert-CVVerification $bad $intent $spec $hash $files} 'Unprotected target observation accepted.'}
$bad=Clone $value;$bad.native.payloadHashes[1]='b'*64;Reject {Assert-CVVerification $bad $intent $spec $hash $files} 'Shadow payload accepted.';$bad=Clone $value;$bad.native.payloadBytesRead=65536;Reject {Assert-CVVerification $bad $intent $spec $hash $files} 'Incomplete read budget accepted.';$bad=Clone $value;$bad.native.snapshots[3].queries=@();Reject {Assert-CVVerification $bad $intent $spec $hash $files} 'Missing snapshot proof accepted.'
foreach($field in @('schemaVersion','kind','runId','observationId','inputSha256','freshVolumeGuid','maximumPayloadBytesRead','targetWriteRequestsMayFollow')){$bad=Clone $intent;$bad.$field='wrong';Reject {Assert-CVVerification $value $bad $spec $hash $files} 'Changed observation intent accepted.'}
$script:removed=0;$script:opened=0;function Remove-PSSession{param($Session)$script:removed++};function Open-RetainedProbeSession{$script:opened++;'new'};function Initialize-LabGuestSession{param($Session)[pscustomobject]@{status='ready'}};function Write-RetainedProbeJson{param($Path,$Value,$Maximum)};function Copy-RetainedProbeGuestSources{}
$outputRoot=$workspace;$script:session='old';$script:transportUnknown=$false;$script:guestOperationUnknown=$false;$script:guestPhaseInFlight=$false
foreach($flag in @('transportUnknown','guestOperationUnknown','guestPhaseInFlight')){Set-Variable -Name $flag -Value $true -Scope Script;Reject {Open-CVFreshSession next} 'Uncertain session boundary accepted.';Check ($script:removed-eq0-and$script:opened-eq0) 'Uncertain handles were cleaned.';Set-Variable -Name $flag -Value $false -Scope Script};Open-CVFreshSession next;Check ($script:removed-eq1-and$script:opened-eq1-and$script:session-ceq'new') 'Fresh known session boundary differs.'
$whatIf=& $path -WhatIf;Check ($whatIf.DryRun-and-not$whatIf.HandoffReplayAllowed) 'WhatIf performed preflight.'
